  # A link is active on its own page and on any page nested under it, so
  # "Clients" stays highlighted on /clients/1/edit.
  def nav_link_to(name, path, icon:)
    active = current_page?(path) || request.path.start_with?("#{path}/")

    link_to path,
      class: class_names(
        "flex items-center gap-x-3 rounded-md px-3 py-2 text-sm font-semibold",
        active ? "bg-navy-800 text-white" : "text-navy-300 hover:bg-navy-800 hover:text-white"
      ),
      aria: { current: ("page" if active) } do
      safe_join([ heroicon(icon, class: [ "size-6 shrink-0", ("text-brand-300" if active) ]), name ])
    end
  end

  def filter_link(label, url, current:)
    link_to label, url, aria: { current: ("true" if current) },
      class: [ "rounded-md px-3 py-1.5", current ? "bg-brand-600 text-white" : "text-gray-600 hover:bg-gray-100 hover:text-gray-900" ]
  end

  # A sortable column header; the controller provides sort_column and sort_direction.
  # Sorting links only carry sort and direction, so pass any other list options
  # (like archived: 1) to keep them when the user sorts.
  def sort_header(label, column, align: :left, filters: {})
    active = column == sort_column
    ascending = active && sort_direction == "asc"
    aria_sort = (ascending ? "ascending" : "descending" if active)

    tag.th scope: "col", class: [ "px-4 py-3", ("text-right" if align == :right) ], aria: { sort: aria_sort } do
      link_to url_for(**filters, sort: column, direction: ascending ? "desc" : "asc"), class: "inline-flex items-center gap-1 hover:text-brand-600" do
        safe_join([ label, (tag.span(ascending ? "▲" : "▼", aria: { hidden: true }) if active) ].compact)
      end
    end
  end

  # Icons are decorative, so screen readers skip them; the text next to them carries the meaning.
  def heroicon(name, **options)
    tag.svg(**options, fill: "none", viewBox: "0 0 24 24", "stroke-width": "1.5", stroke: "currentColor", aria: { hidden: true }) do
      safe_join(Array(ICONS.fetch(name)).map { tag.path("stroke-linecap": "round", "stroke-linejoin": "round", d: it) })
    end
  end
